for a0 in 0..128:
    for a1 in 0..128:
        for a2 in 0..256:
            in0 = load x0[a0, a2]
            in1 = load x1[a2, a1]
            v0 = multiply(in0, in1)
            acc0 <- add(acc0, v0) over a2
        bf16 v1 = copy(acc0)
        i32 v2 = to_f4e2m1(v1)
        codes[a0, a1] = v2
